-- Study Abroad country content, BATCH 4: Switzerland, Austria, Denmark, Finland, Poland.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('switzerland', 'austria', 'denmark', 'finland', 'poland'));
UPDATE countries SET why_title = 'Why study in Switzerland?', why_body = '<p>Switzerland combines world-class research universities with high living standards and multilingual cities. In the QS World University Rankings 2027, ETH Zurich is 8th and EPFL joint 22nd.</p><ul><li>Strong in engineering, science, finance, hospitality and life sciences</li><li>Research links with global companies such as Nestle, Roche and Novartis</li><li>Teaching in German, French, Italian and, increasingly, English at Master''s level</li><li>Graduates may stay to look for work after their degree</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students from outside the EU/EFTA need a <strong>national visa (type D)</strong> and then a residence permit from the cantonal migration office after arrival.</p><ul><li>Admission letter from a Swiss university</li><li>Proof of funds: about CHF 21,000 a year is the most common figure, and some cantons ask for more (for example CHF 24,000 in Vaud or Geneva)</li><li>Health insurance valid in Switzerland (compulsory)</li><li>Passport, CV and academic records; a motivation letter for some cases</li><li>Processing usually takes 4-12 weeks, so apply early</li><li>Graduates may stay for a limited period to look for work (check the current rule with the canton)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Swiss State Secretariat for Migration (sem.admin.ch) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Bachelor''s deadlines are often in spring for the autumn start, and Master''s deadlines vary by programme.</p><ul><li>Academic transcripts and certificates, with translations where needed</li><li>Proof of language (English, German or French)</li><li>Motivation letter and CV</li><li>Letters of recommendation for Master''s and PhD</li><li>GRE or GMAT for some programmes</li><li>Passport copy and application fee (often CHF 100-200)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition at public universities is low by international standards, but living costs are among the highest in the world.</p><ul><li>Tuition at public universities is relatively low compared with the US or UK; some institutions charge international students more, so check each university</li><li>Private universities and hotel schools charge much more</li><li>Living costs: CHF 1,700-2,500 a month depending on the city (funds guide is about CHF 21,000 a year)</li><li>Health insurance: roughly CHF 300-400 a month for students (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a school-leaving certificate recognised by the university; many students from outside Europe need extra qualifications or a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with strong grades</li><li><strong>Language:</strong> IELTS 6.5 or TOEFL 85-100 for English-taught courses; German (C1) or French (C1) for local-language courses</li><li>Some universities need GRE or an entrance test</li></ul>' WHERE slug = 'switzerland';
UPDATE countries SET why_title = 'Why study in Austria?', why_body = '<p>Austria has historic universities, a high quality of life and low public tuition compared with many countries. Vienna is regularly ranked among the world''s most liveable cities.</p><ul><li>Low tuition at public universities, even for non-EU students</li><li>Strong in music, arts, engineering, medicine and business</li><li>A growing choice of English-taught Master''s programmes</li><li>Graduates may stay to look for work after their degree</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>residence permit for students (Aufenthaltsbewilligung Student)</strong>, applied for at the Austrian embassy before travel, then a residence card after arrival.</p><ul><li>Admission letter or confirmation from an Austrian university</li><li>Proof of funds for the first 12 months: figures vary with your age and rent; reported between about €613 and €1,300 a month, so check the OeAD checklist</li><li>Health insurance valid in Austria (public or private)</li><li>Application fee: reported at about €218 for 2026</li><li>Proof of accommodation, passport and academic records</li><li>Work: students may work in a limited way (usually up to 20 hours a week with a work permit)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official OeAD and the Austrian embassy site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Non-EU applicants usually have earlier deadlines than EU applicants.</p><ul><li>Academic transcripts and certificates, with translations</li><li>Proof of language: German (usually B2) or English</li><li>CV and motivation letter</li><li>Entrance exam or portfolio for some programmes (for example music, art and medicine)</li><li>Passport copy</li><li>Proof of funds for the residence permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities charge a low tuition fee for non-EU students, plus a small student union fee. Private universities charge much more.</p><ul><li>Public universities: about €726 per semester for non-EU students, plus the student union contribution (reported figure)</li><li>Private universities: roughly €5,000-€20,000+ a year</li><li>Living costs: about €1,000-€1,300 a month; Vienna is more expensive than other cities</li><li>Student health insurance: about €79 a month (reported 2026 figure)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a school certificate that gives access to university in your country, often with extra subjects; many programmes need an entrance test</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> German B2 or C1 for German-taught courses; IELTS 6.0-6.5 or TOEFL 80+ for English-taught courses</li><li>Some courses have limited places and entrance exams</li></ul>' WHERE slug = 'austria';
UPDATE countries SET why_title = 'Why study in Denmark?', why_body = '<p>Denmark is known for innovation, sustainability, design and a flat, project-based teaching style. Its universities offer many English-taught programmes and strong links with industry.</p><ul><li>Strong in engineering, sustainable energy, design and life sciences</li><li>Teaching based on group work and problem solving</li><li>Home to companies such as Novo Nordisk, Maersk and Vestas</li><li>Graduates may apply to stay and look for work</li></ul>', visa_title = 'Student residence permit requirements', visa_body = '<p>Non-EU students need a <strong>residence permit for studies</strong> from the Danish Agency for International Recruitment and Integration (SIRI). You apply online with your admission letter.</p><ul><li>Admission letter from a Danish institution</li><li>Proof of funds: DKK 7,426 a month (2026 level), or a scholarship or loan; paid tuition for the first semester counts as proof of funds for that part</li><li>Processing fee: DKK 3,060, paid before applying</li><li>Normal processing time: about 2 months, sometimes 3</li><li>Work: students get a limited work permit with the residence permit</li><li>Graduates may apply for a permit to look for work after graduation (check current rules)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official SIRI (nyidanmark.dk) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Bachelor''s applications are usually made through the national portal (optagelse.dk); Master''s applications are made directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof (IELTS or TOEFL)</li><li>Motivation letter and CV for Master''s programmes</li><li>Letters of recommendation for some courses</li><li>Passport copy</li><li>Proof of funds for the residence permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is free for EU/EEA students but not for non-EU students. Living costs are high, especially in Copenhagen.</p><ul><li>Tuition (non-EU): roughly DKK 45,000-120,000 a year, depending on the course</li><li>Living costs: about DKK 7,426 a month is the SIRI guide for 2026</li><li>Residence permit fee: DKK 3,060</li><li>Health: students with a residence permit normally have access to Danish health services</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the programme.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with required subjects at the right level (often mathematics and English)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, usually with a strong grade</li><li><strong>English:</strong> IELTS 6.5 or TOEFL 83-90+ for most programmes</li><li>Some programmes have limited places and select on grades</li></ul>' WHERE slug = 'denmark';
UPDATE countries SET why_title = 'Why study in Finland?', why_body = '<p>Finland is known for education quality, innovation and high living standards. Universities are strong in technology, forestry, education and design, with many English-taught degrees.</p><ul><li>Strong in technology, education, design and forestry</li><li>Teaching based on practical learning and small groups</li><li>Aalto and Helsinki are among the leading Nordic universities</li><li>Graduates may apply for a permit to look for work after their studies</li></ul>', visa_title = 'Student residence permit requirements', visa_body = '<p>Students from outside the EU/EEA need a <strong>residence permit for studies</strong> from the Finnish Immigration Service (Migri), applied for online with your admission letter.</p><ul><li>Admission letter from a Finnish institution</li><li>Proof of funds: about €800 a month (€9,600 for the first year), in addition to tuition</li><li>Proof of paid tuition fee, if you are required to pay one</li><li>Application fee: electronic fee reported at €350 to €450 (check Migri for the current figure)</li><li>Health insurance valid in Finland if you stay less than 2 years</li><li>Work: students may work up to about 30 hours a week</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Migri (migri.fi) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most universities use the national <strong>Studyinfo</strong> portal for degree applications, with set application windows.</p><ul><li>Academic transcripts and certificates, certified</li><li>Proof of English proficiency</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exam or portfolio for some programmes</li><li>Passport copy</li><li>Proof of funds for the residence permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Non-EU/EEA students pay tuition for English-taught degree programmes. Living costs are moderate by Nordic standards.</p><ul><li>Tuition (non-EU): usually from about €4,000 and often €8,000-€18,000 a year, depending on the programme</li><li>Living costs: about €800-€1,000 a month (funds guide is €800)</li><li>Residence permit fee: reported at €350-€450</li><li>Student housing is cheaper than private rent but limited</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with strong results; many courses use entrance exams</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 6.0-6.5 or TOEFL 80-90, depending on the programme</li><li>Some programmes ask for GRE, GMAT or a portfolio</li></ul>' WHERE slug = 'finland';
UPDATE countries SET why_title = 'Why study in Poland?', why_body = '<p>Poland offers low tuition and living costs, a large number of English-taught programmes and strong universities in medicine, engineering and IT, in the centre of Europe.</p><ul><li>Lower tuition and living costs than most Western European countries</li><li>English-taught Bachelor''s, Master''s and medicine programmes</li><li>Students with a visa or residence permit can work without a separate work permit</li><li>A fast-growing IT and business sector</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students usually enter on a national <strong>type D student visa</strong>, then apply for a <strong>temporary residence permit (TRC)</strong> if they stay longer than the visa allows.</p><ul><li>Admission letter from a Polish university and proof of tuition payment for the semester or year</li><li>Proof of funds for living costs (a monthly amount set by the local office, often paid in advance for the first period) and a return ticket where required</li><li>Health insurance and proof of premium payment</li><li>Passport, photos and application forms</li><li>Application system: Polish authorities introduced a new online portal for residence permits in April 2026, so check the current procedure</li><li>Work: students holding a student visa or permit may work without a work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Polish migration office (UdSC) and the university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most universities take applications online through their own portal. Some use the national admission platform for undergraduate courses.</p><ul><li>Academic transcripts and certificates, with translations</li><li>English proficiency or a language certificate</li><li>Entrance exam, interview or portfolio for some programmes (for example medicine)</li><li>Motivation letter and CV for Master''s programmes</li><li>Passport copy and photographs</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for non-EU students is lower than in most Western European countries; fees vary by university and course.</p><ul><li>Tuition (non-EU): roughly €2,000-€6,000 a year for most programmes; medicine and dentistry cost more</li><li>Living costs: about PLN 2,500-4,000 a month in major cities</li><li>Health insurance: required for the visa and residence permit</li><li>Visa fee: reported at about €80</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and programme.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school; some courses need specific subjects or an entrance test</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent, depending on the course</li><li>Medicine and dentistry usually need an entrance exam in biology and chemistry</li></ul>' WHERE slug = 'poland';
COMMIT;
